use std::path::PathBuf;
use serde_json::json;
use dirs::config_dir;

pub fn get_config_dir() -> PathBuf {
    config_dir().unwrap_or_else(|| PathBuf::from(".config")).join("tree-sitter")
}

pub fn load_config(config_path: Option<PathBuf>) -> serde_json::Value {
    let config_file = config_path.unwrap_or_else(|| get_config_dir().join("config.json"));

    if config_file.exists() {
        if let Ok(content) = std::fs::read_to_string(&config_file) {
            if let Ok(value) = serde_json::from_str(&content) {
                return value;
            }
        }
    }

    json!({})
}
EOF

