mod commands;
use commands::*;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let command = &args[1];

    match command.as_str() {
        "-h" | "--help" => print_help(),
        "-V" | "--version" => println!("tree-sitter 0.27.0"),
        "init-config" => init_config::handle(),
        "init" => init::handle(&args[2..]),
        "generate" => generate::handle(&args[2..]),
        "build" => build::handle(&args[2..]),
        "parse" => parse::handle(&args[2..]),
        "test" => test::handle(&args[2..]),
        "version" => version::handle(&args[2..]),
        "fuzz" => fuzz::handle(&args[2..]),
        "query" => query::handle(&args[2..]),
        "highlight" => highlight::handle(&args[2..]),
        "tags" => tags::handle(&args[2..]),
        "playground" => playground::handle(&args[2..]),
        "dump-languages" => dump_languages::handle(&args[2..]),
        "complete" => complete::handle(&args[2..]),
        _ => {
            eprintln!("Unknown command: {}", command);
            print_help();
        }
    }
}

fn print_help() {
    println!("tree-sitter 0.27.0");
    println!("Max Brunsfeld <maxbrunsfeld@gmail.com>");
    println!("Amaan Qureshi <amaanq12@gmail.com>");
    println!("Generates and tests parsers");
    println!();
    println!("Usage: executable <COMMAND>");
    println!();
    println!("Commands:");
    println!("  init-config     Generate a default config file");
    println!("  init            Initialize a grammar repository");
    println!("  generate        Generate a parser");
    println!("  build           Compile a parser");
    println!("  parse           Parse files");
    println!("  test            Run a parser's tests");
    println!("  version         Display or increment the version of a grammar");
    println!("  fuzz            Fuzz a parser");
    println!("  query           Search files using a syntax tree query");
    println!("  highlight       Highlight a file");
    println!("  tags            Generate a list of tags");
    println!("  playground      Start local playground for a parser in the browser");
    println!("  dump-languages  Print info about all known language parsers");
    println!("  complete        Generate shell completions");
    println!();
    println!("Options:");
    println!("  -h, --help     Print help");
    println!("  -V, --version  Print version");
}
EOF

