use std::collections::HashMap;
use std::path::PathBuf;

pub struct Args {
    pub options: HashMap<String, String>,
    pub flags: HashMap<String, bool>,
    pub positional: Vec<String>,
}

impl Args {
    pub fn parse(args: &[String]) -> Self {
        let mut options = HashMap::new();
        let mut flags = HashMap::new();
        let mut positional = Vec::new();

        let mut i = 0;
        while i < args.len() {
            let arg = &args[i];

            if arg.starts_with("--") {
                let arg_name = &arg[2..];

                if let Some(eq_pos) = arg_name.find('=') {
                    let key = arg_name[..eq_pos].to_string();
                    let value = arg_name[eq_pos + 1..].to_string();
                    options.insert(key, value);
                } else if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    let key = arg_name.to_string();
                    let value = args[i + 1].clone();
                    options.insert(key, value);
                    i += 1;
                } else {
                    flags.insert(arg_name.to_string(), true);
                }
            } else if arg.starts_with("-") && arg != "-" {
                let arg_name = &arg[1..];

                if arg_name.len() == 1 {
                    // Single letter flag
                    if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                        let key = arg_name.to_string();
                        let value = args[i + 1].clone();
                        options.insert(key, value);
                        i += 1;
                    } else {
                        flags.insert(arg_name.to_string(), true);
                    }
                } else {
                    // Multiple short flags or long flag without --
                    flags.insert(arg_name.to_string(), true);
                }
            } else {
                positional.push(arg.clone());
            }

            i += 1;
        }

        Args {
            options,
            flags,
            positional,
