        println!("  -p, --grammar-path <GRAMMAR_PATH>  The path to the tree-sitter grammar directory, implies --rebuild");
        println!("  -l, --lib-path <LIB_PATH>          The path to the parser's dynamic library");
        println!("      --lang-name <LANG_NAME>        If `--lib-path` is used, the name of the language used to extract the library's language function");
        println!("  -u, --update                       Update all syntax trees in corpus files with current parser output");
        println!("  -d, --debug                        Show parsing debug log");
        println!("  -0, --debug-build                  Compile a parser in debug mode");
        println!("  -D, --debug-graph                  Produce the log.html file with debug graphs");
        println!("      --open-log                     Open `log.html` in the default browser, if `--debug-graph` is supplied");
        println!("      --config-path <CONFIG_PATH>    The path to an alternative config.json file");
        println!("      --show-fields                  Force showing fields in test diffs");
        println!("      --stat <STAT>                  Show parsing statistics [possible values: all, outliers-and-total, total-only]");
        println!("  -r, --rebuild                      Force rebuild the parser");
        println!("      --overview-only                Show only the pass-fail overview tree");
        println!("      --json-summary                 Output the test summary in a JSON format");
        println!("  -h, --help                         Print help");
        return;
    }
}
