        println!();
        println!("Usage: executable query [OPTIONS] <QUERY_PATH> [PATHS]...");
        println!();
        println!("Arguments:");
        println!("  <QUERY_PATH>  Path to a file with queries");
        println!("  [PATHS]...    The source file(s) to use");
        println!();
        println!("Options:");
        println!("  -p, --grammar-path <GRAMMAR_PATH>");
        println!("          The path to the tree-sitter grammar directory, implies --rebuild");
        println!("  -l, --lib-path <LIB_PATH>");
        println!("          The path to the parser's dynamic library");
        println!("      --lang-name <LANG_NAME>");
        println!("          If `--lib-path` is used, the name of the language used to extract the library's language function");
        println!("  -t, --time");
        println!("          Measure execution time");
        println!("  -q, --quiet");
        println!("          Suppress main output");
        println!("      --paths <PATHS_FILE>");
        println!("          The path to a file with paths to source file(s)");
        println!("      --byte-range <BYTE_RANGE>");
        println!("          The range of byte offsets in which the query will be executed");
        println!("      --row-range <ROW_RANGE>");
        println!("          The range of rows in which the query will be executed");
        println!("      --containing-byte-range <CONTAINING_BYTE_RANGE>");
        println!("          The range of byte offsets in which the query will be executed. Only the matches that are fully contained within the provided byte range will be returned");
        println!("      --containing-row-range <CONTAINING_ROW_RANGE>");
        println!("          The range of rows in which the query will be executed. Only the matches that are fully contained within the provided row range will be returned");
        println!("      --scope <SCOPE>");
        println!("          Select a language by the scope instead of a file extension");
        println!("  -c, --captures");
        println!("          Order by captures instead of matches");
        println!("      --test");
        println!("          Whether to run query tests or not");
        println!("      --config-path <CONFIG_PATH>");
        println!("          The path to an alternative config.json file");
        println!("  -n, --test-number <TEST_NUMBER>");
        println!("          Query the contents of a specific test");
        println!("  -r, --rebuild");
        println!("          Force rebuild the parser");
        println!("  -h, --help");
        println!("          Print help");
        return;
    }
}
EOF

