        println!("      --lang-name <LANG_NAME>        If `--lib-path` is used, the name of the language used to extract the library's language function");
        println!("      --scope <SCOPE>                Select a language by the scope instead of a file extension");
        println!("  -d, --debug [<DEBUG>]              Show parsing debug log [possible values: quiet, normal, pretty]");
        println!("  -0, --debug-build                  Compile a parser in debug mode");
        println!("  -D, --debug-graph                  Produce the log.html file with debug graphs");
        println!("      --dot                          Output the parse data with graphviz dot");
        println!("  -x, --xml                          Output the parse data in XML format");
        println!("  -c, --cst                          Output the parse data in a pretty-printed CST format");
        println!("  -s, --stat                         Show parsing statistic");
        println!("      --timeout <TIMEOUT>            Interrupt the parsing process by timeout (µs)");
        println!("  -t, --time                         Measure execution time");
        println!("  -q, --quiet                        Suppress main output");
        println!("      --edits <EDITS>...             Apply edits in the format: \\\"row,col|position delcount insert_text\\\", can be supplied multiple times");
        println!("      --encoding <ENCODING>          The encoding of the input files [possible values: utf8, utf16-le, utf16-be]");
        println!("      --open-log                     Open `log.html` in the default browser, if `--debug-graph` is supplied");
        println!("      --json                         Deprecated: use --json-summary");
        println!("  -j, --json-summary                 Output parsing results in a JSON format");
        println!("      --config-path <CONFIG_PATH>    The path to an alternative config.json file");
        println!("  -n, --test-number <TEST_NUMBER>    Parse the contents of a specific test");
        println!("  -r, --rebuild                      Force rebuild the parser");
        println!("      --no-ranges                    Omit ranges in the output");
        println!("  -h, --help                         Print help");
        return;
    }
}
