use std::fs;
use std::path::PathBuf;
use super::Args;

pub fn handle(args: &[String]) {
    let _parsed = Args::parse(args);

    if _parsed.has("h") || _parsed.has("help") {
        println!("Generate a default config file");
        println!();
        println!("Usage: executable init-config");
        println!();
        println!("Options:");
        println!("  -h, --help  Print help");
        return;
    }

    let config_dir = get_config_dir();

    // Create the config directory if it doesn't exist
    let _ = fs::create_dir_all(&config_dir);

    let config_file = config_dir.join("config.json");

    // Create a default config
    let config_content = r#"{
  "parser-directories": [
    "./node_modules/tree-sitter-*/",
    "~/.tree-sitter/parsers/"
  ]
}"#;

    // Write the config file
    let _ = fs::write(&config_file, config_content);
    println!("Saved initial configuration to {}", config_file.display());
}

fn get_config_dir() -> PathBuf {
    if let Ok(home) = std::env::var("HOME") {
        PathBuf::from(home).join(".config/tree-sitter")
    } else {
        PathBuf::from(".config/tree-sitter")
    }
}
EOF

